    // ── EC1: Special float arithmetic + MathF (sqrt/sin/log for Inf/NaN/0/negative) ──
    public struct EdgeCase1_CSharp_For : IJobFor
    {
        public NativeArray<float> A, R;
        public void Execute(int i)
        {
            float a = A[i];
            float r;
            if (a > 10f)
            {
                r = a * 2f + MathF.Sqrt(a);
                if (a > 100f) r += MathF.Sin(a);
                else if (a > 50f) r -= MathF.Cos(a);
                else r += MathF.Log(a);
            }
            else if (a > -1f)
            {
                r = a * a - 3f;
                if (a != 0f) r = r / a;
                else r = 1234.5f;
            }
            else
            {
                r = -a * 0.5f;
                r += MathF.Log(-a);
            }
            R[i] = r;
        }
    }

