    // ── EC3: int overflow boundary (INT_MIN/MAX arithmetic + unsigned compare) ──
    public struct EdgeCase3_CSharp_For : IJobFor
    {
        public NativeArray<int> A, B, R;
        public void Execute(int i)
        {
            int x = A[i];
            int y = B[i];
            if ((uint)x > (uint)y)
            {
                int sum = unchecked(x + y);
                R[i] = (sum ^ y) + (x * 3);
            }
            else if (x == int.MinValue)
            {
                R[i] = unchecked(-x);
            }
            else if (y == -1 && x == int.MaxValue)
            {
                R[i] = x * y;
            }
            else
            {
                R[i] = (x >> 1) ^ (y << 2) & ~3;
            }
        }
    }

