    // ── EC4: Multi-level && / || mixed continue (De Morgan hybrid) ──
    public struct EdgeCase4_CSharp_For : IJobFor
    {
        public NativeArray<float> A, R;
        public void Execute(int i)
        {
            int cx = i % 20, cy = (i / 20) % 20;
            float sum = 0f;
            for (int dx = -2; dx <= 2; dx++)
            {
                int nx = cx + dx;
                if ((nx < 0 || nx >= 20) || (dx == 0 && i % 3 == 0)) continue;
                for (int dy = -2; dy <= 2; dy++)
                {
                    if ((dx == 0 && dy == 0) || (dx + dy == 0 && (i & 1) == 1)) continue;
                    int ny = cy + dy;
                    if ((uint)ny >= 20u || dx * dy > 2) continue;
                    float v = A[ny * 20 + nx];
                    if (v > 5f && v < 50f) sum += v;
                    else if (v < -5f || v > 100f) sum -= v * 0.25f;
                    else sum += 1f;
                }
            }
            R[i] = sum;
        }
    }

