                    else sum += 1f;
                }
            }
            R[i] = sum;
        }
    }

    // ── EC5: Nested loop return (early exit + computed result) ──
    public struct EdgeCase5_CSharp_For : IJobFor
    {
        public NativeArray<float> A, R;
        public void Execute(int i)
        {
            for (int j = 0; j < 8; j++)
            {
                for (int k = j; k < 8; k++)
                {
                    float v = A[i * 64 + j * 8 + k];
                    if (v > 1000f) { R[i] = j * 10f + k * 1.5f; return; }
                    if (v < -1000f) { R[i] = -j - k; return; }
                }
            }
            R[i] = 777f;
        }
    }

