    // ── EC6: Non-constant loop bound + branch (bound depends on runtime data; pure float accumulation) ──
    public struct EdgeCase6_CSharp_For : IJobFor
    {
        public NativeArray<float> A, R;
        public NativeArray<int> Counts;
        public void Execute(int i)
        {
            int n = Counts[i] & 31;
            float acc = 0f;
            for (int j = 0; j < n; j++)
            {
                float v = A[i * 32 + j];
                if (v > 0f) acc += v;
                else if (v < -0.5f) acc -= v;
                else acc += 0.01f;
            }
            if (acc > 3f) R[i] = acc * 2f;
            else R[i] = acc + 0.25f;
        }
    }

